<script setup lang="ts">
import EventReadState from './EventReadState.vue';
import {title as displayTitle,sourceName,indicator,utc,time as beijingTime,duration,http} from '../presentation/zh';
import {ref,onMounted,computed} from 'vue';import {post,safeOfficialUrl} from '../api/client';
const props=defineProps<{token:string}>();type Row=Record<string,any>;const tab=ref('我的关注'),busy=ref(false),error=ref(''),catalog=ref<Row>({}),watches=ref<Row[]>([]),radar=ref<Row[]>([]),series=ref<Row[]>([]),research=ref<Row[]>([]),selected=ref<Row>(),bls=ref<Row>({}),audit=ref<Row>({}),trace=ref<Row[]>([]),relations=ref<Row[]>([]),ai=ref<Row>({}),page=ref(0),kind=ref('SOURCE'),value=ref(''),priority=ref(0),leads=ref(false),chosenSeries=ref(''),snapshot=ref('');
const names:Record<string,string>={COUNTRY:'国家或区域',CENTRAL_BANK:'央行',INDICATOR:'宏观指标',INSTITUTION:'金融机构',COMPANY:'法人公司（不推断上市证券）',INDUSTRY:'产业主题（规则标签）',EVENT_TYPE:'金融事件类别',SOURCE:'官方来源',INSUFFICIENT:'证据不足',EXPIRED:'已失效',CONFIRMED:'已确认',REJECTED:'已拒绝',PENDING:'待审核',SUFFICIENT:'证据足够',NOT_DELIVERED:'尚未投递',ACKNOWLEDGED:'已确认接收',SENT:'已发送',FAILED:'失败',SUCCESS:'成功',RUNNING:'运行中',SKIPPED:'已跳过'};
const options=computed<Row[]>(()=>{const c=catalog.value;if(kind.value==='COUNTRY')return [...new Set((c.sources||[]).map((s:Row)=>s.region))].map(x=>({id:x,title:x}));if(kind.value==='CENTRAL_BANK')return(c.sources||[]).filter((s:Row)=>['FED','ECB'].includes(s.id)).map((s:Row)=>({id:s.id,title:sourceName(s.id,s.name)}));if(kind.value==='SOURCE')return(c.sources||[]).map((s:Row)=>({id:s.id,title:sourceName(s.id,s.name)}));if(kind.value==='INSTITUTION')return(c.sources||[]).map((s:Row)=>({id:s.name,title:sourceName(s.id,s.name)}));return kind.value==='INDICATOR'?c.indicators||[]:kind.value==='COMPANY'?c.companies||[]:kind.value==='EVENT_TYPE'?c.event_types||[]:(c.topics||[]).map((x:Row)=>({id:x.id,title:x.id}));});
const time=beijingTime;async function action(f:()=>Promise<void>){busy.value=true;error.value='';try{await f();snapshot.value=new Date().toISOString();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function load(){await action(async()=>{if(tab.value==='我的关注'){catalog.value=await post<Row>('/watch/catalog',props.token);watches.value=await post<Row[]>('/watch/query',props.token);radar.value=await post<Row[]>('/watch/radar',props.token,{page:page.value});}if(tab.value==='宏观研究'){series.value=await post<Row[]>('/macro-research/catalog',props.token);research.value=await post<Row[]>('/macro-research/history',props.token,{page:page.value});}if(tab.value==='BLS官方数据')bls.value=await post<Row>('/bls/status',props.token);if(tab.value==='消息资格审计'){audit.value=await post<Row>('/qualification/status',props.token);trace.value=await post<Row[]>('/qualification/recompute',props.token,{after:0,limit:30});}if(tab.value==='关系证据审计')relations.value=await post<Row[]>('/relation-assessment/history',props.token);if(tab.value==='AI评测准备')ai.value=await post<Row>('/ai-evaluation/status',props.token);});}
async function add(){await action(async()=>{const label=options.value.find(x=>x.id===value.value)?.title;if(!label)throw Error('请选择真实目录中的关注目标');watches.value=await post<Row[]>('/watch/add',props.token,{kind:kind.value,value:value.value,label,includeLeads:leads.value,minimumPriority:priority.value});radar.value=await post<Row[]>('/watch/radar',props.token,{page:0});});}
async function remove(id:string){await action(async()=>{watches.value=await post<Row[]>('/watch/remove',props.token,{id});radar.value=await post<Row[]>('/watch/radar',props.token,{page:0});});}
async function analyze(){await action(async()=>{selected.value=await post<Row>('/macro-research/analyze',props.token,{series:chosenSeries.value,asOf:new Date().toISOString()});research.value=await post<Row[]>('/macro-research/history',props.token,{page:0});});}
async function relationAudit(){await action(async()=>{await post('/relation-assessment/audit',props.token);relations.value=await post<Row[]>('/relation-assessment/history',props.token);});}async function prepare(){await action(async()=>{ai.value=await post<Row>('/ai-evaluation/prepare',props.token);});}
const reportNames:Record<string,string>={title:'事件标题',fact_summary:'事实摘要',official_source:'官方来源',published_at:'官方发布时间',key_numbers:'关键数字与实际比较',history:'历史背景',institutions:'发布机构',mechanism:'影响机制',possible_markets:'可能关联市场',positive_hypotheses:'正向条件假设',negative_hypotheses:'负向条件假设',counter_evidence:'反面证据',gaps:'数据缺口',watch_variables:'观察指标',validity:'有效期与失效条件',market_status:'市场验证状态'};
onMounted(load);
</script>
<template><section class="panel workbench"><div class="section-title"><h2>用户关注与金融研究雷达</h2><button :disabled="busy" @click="load">刷新实际数据</button></div><div class="tabs"><button v-for="name in ['我的关注','宏观研究','BLS官方数据','消息资格审计','关系证据审计','AI评测准备']" :class="{primary:tab===name}" @click="tab=name;page=0;selected=undefined;load()">{{name==='BLS官方数据'?'美国劳工统计局（BLS）官方数据':name==='AI评测准备'?'人工智能（AI）评测准备':name}}</button></div><p>查询时间 <time :title="'UTC原值：'+utc(snapshot)">{{time(snapshot)}}</time> · 研究候选与重大提醒分开；雷达不等同买卖建议。</p><p v-if="error" role="alert">{{error}}</p>
<template v-if="tab==='我的关注'"><div class="filters"><select v-model="kind" aria-label="关注类型" @change="value=''"><option v-for="k in ['COUNTRY','CENTRAL_BANK','INDICATOR','INSTITUTION','COMPANY','INDUSTRY','EVENT_TYPE','SOURCE']" :value="k">{{names[k]}}</option></select><select v-model="value" aria-label="关注目标"><option value="">请选择真实关注目标</option><option v-for="o in options" :value="o.id">{{sourceName(o.id,indicator(o.id)||o.title)}}{{kind==='INDICATOR'?'（指标代码：'+o.id+'）':''}}</option></select><label>最低规则优先级<input v-model.number="priority" type="number" min="0" max="100" aria-label="关注最低优先级"></label><label><input v-model="leads" type="checkbox">允许待核聚合线索</label><button :disabled="busy||!value" @click="add">保存关注</button></div><p>关注设置存储在数据库，按当前访问身份隔离。规则标签不能证明产业归属；法人身份不能证明上市证券或供应链。</p><p v-if="!watches.some(x=>x.enabled)">暂无关注条件，请从真实目录选择。</p><article v-for="w in watches.filter(x=>x.enabled)" :key="w.id"><b>{{names[w.kind]}} · {{w.label}}</b><p>规则优先级至少 {{w.minimum_priority}} · 聚合线索 {{w.include_leads?'允许':'关闭'}}</p><button @click="remove(w.id)">取消关注</button></article><h3>关注研究候选</h3><p v-if="!radar.length">暂无符合关注条件的真实消息</p><article v-for="e in radar" :key="e.id" :data-radar-id="e.id"><h3>{{displayTitle(e).text}}</h3><p class="muted">{{displayTitle(e).status}}</p><EventReadState :id="e.id" :version="e.collected_at"/><details><summary>查看原文标题</summary><p class="original">{{e.original_title}}</p></details><p>{{sourceName(e.source_id,e.publisher)}} · {{e.level==='L0'?'官方来源':'待核聚合线索'}} · 研究优先级 {{e.priority}}</p><p>官方发布 <time :title="'UTC原值：'+utc(e.published_at)">{{time(e.published_at,'官方发布时间未知')}}</time> · 采集 <time :title="'UTC原值：'+utc(e.collected_at)">{{time(e.collected_at)}}</time> · {{e.ingestion_kind==='HISTORICAL_BACKFILL'?'历史回填，不实时提醒':'消息性质以资格审计为准'}}</p><p>{{e.rejection_reason||'没有取得重大提醒审核依据'}} · {{e.match_basis}}</p><a v-if="safeOfficialUrl(e.source_url)" :href="e.source_url" target="_blank" rel="noopener noreferrer">查看原始来源</a><a :href="'#/research?event='+e.id">查看金融事件研究详情</a></article><button :disabled="page===0" @click="page--;load()">上一页</button><button :disabled="radar.length<50" @click="page++;load()">下一页</button></template>
<template v-if="tab==='宏观研究'"><div class="filters"><select v-model="chosenSeries" aria-label="研究指标"><option value="">选择实际已入库指标</option><option v-for="s in series" :value="s.id">{{indicator(s.id)||'中文指标名称待核验'}} · {{s.id}}</option></select><button :disabled="busy||!chosenSeries" @click="analyze">生成证据截止快照</button></div><p>原子字段数不等同独立经济事件数。没有合法预期数据时不计算超预期；输入取得时间晚于截止时间时禁止使用。</p><p v-if="!research.length">暂无真实研究快照</p><article v-for="r in research" :key="r.id"><h3>{{indicator(r.series_id)||'同口径宏观研究快照'}}</h3><details><summary>查看研究输入原始名称</summary><p>{{r.report.title}}</p></details><p>同口径规则 {{r.rule_version}} · 证据截止 <time :title="'UTC原值：'+utc(r.as_of)">{{time(r.as_of)}}</time> · 实际生成 <time :title="'UTC原值：'+utc(r.created_at)">{{time(r.created_at)}}</time></p><button @click="selected=r">查看输入与研究局限</button></article></template>
<template v-if="tab==='BLS官方数据'"><p>{{bls.state}}</p><p>最近24小时保守预算 {{bls.requests_last_24h??0}} / {{bls.daily_limit??25}} · 实际月度观测 {{bls.observations??0}}</p><p>来源：美国劳工统计局；数据取得时间见证据。美国劳工统计局不保证数据下载后所衍生数据或分析的质量。BLS统计不是秒级交易行情。</p><article v-for="s in bls.series" :key="s.id"><h3>{{indicator(s.id)||'中文指标名称待核验'}}</h3><p>{{s.id}} · {{s.unit||'单位尚待官方核实'}} · {{s.verified?'定义已核对':'定义或单位待核对'}} · {{s.enabled?'允许人工采集':'采集保持关闭'}}</p><a :href="s.definition_url" target="_blank" rel="noopener noreferrer">查看官方序列定义</a></article><article v-for="r in bls.requests" :key="r.id"><p><time :title="'UTC原值：'+utc(r.started_at)">{{time(r.started_at)}}</time> · {{http(r.http_status)}} · 官方API状态 {{r.api_status||'未返回'}}</p><p>{{r.error||'请求结果保留，不能仅凭HTTP200认定数据成功'}}</p><p>SHA-256 {{r.sha256||'未取得响应字节'}}</p></article></template>
<template v-if="tab==='消息资格审计'"><p>重大资格通知位置 {{audit.qualification_positions??0}} · 新增消息自动审计 {{audit.trace_count??0}}</p><p>以下为只读历史重算，不新增Outbox、不产生实时提醒；官方消息投递与重大资格分别判断。</p><article v-for="r in audit.reasons"><b>{{r.qualified?'重大资格符合':'重大资格未通过'}}</b><p>{{r.rejection_reason||'以资格与当前事实核验为准'}} · {{r.records}}条</p></article><article v-for="r in trace" :key="r.id"><p>来源 {{sourceName(r.source_id)}} · {{r.event_type}} · 规则 {{r.qualification_rule_version}}</p><p>{{r.rejection_reason||'资格符合'}} · 实际投递状态 {{names[r.delivery_status]||r.delivery_status}}</p></article><h3>采集任务与事务提交口径</h3><article v-for="r in audit.task_accounting"><p>{{sourceName(r.source_id)}} · {{names[r.task_status]||r.task_status}} · {{r.commit_state==='PARTIAL_COMMITTED'?'任务失败，部分批次已提交':r.commit_state==='NO_RECORD_COMMIT'?'未提交业务记录':r.commit_state==='IN_PROGRESS'?'任务运行中':'任务完成'}} · {{r.tasks}}项</p><p>实际已提交原始证据 {{r.committed_records}} 条、独立历史版本 {{r.committed_history_versions??0}} 条；{{r.counter_state==='COUNTER_MISMATCH'?'声明计数与实际保存不一致，待核查':'实际记录口径已列出'}}</p></article></template>
<template v-if="tab==='关系证据审计'"><button :disabled="busy" @click="relationAudit">执行真实证据自动审计</button><p>自动审计不冒充人工确认；登记时间不等同首次公开时间；会计合并不等同客户或供应链。</p><p v-if="!relations.length">暂无关系审计记录</p><article v-for="r in relations" :key="r.id"><b>{{names[r.assessment]||r.assessment}} · 自动证据审计</b><p><time :title="'UTC原值：'+utc(r.assessed_at)">{{time(r.assessed_at)}}</time> · {{r.rule_version}}</p><p>{{r.limitations}}</p><pre>{{JSON.stringify(r.checks,null,2)}}</pre></article></template>
<template v-if="tab==='AI评测准备'"><p>{{ai.provider?.state}}</p><p>真实执行 {{ai.provider?.executions??0}} · {{ai.state}}</p><button :disabled="busy" @click="prepare">准备已有官方证据评测样本</button><p>{{ai.retry_policy}}</p><p>评测任务 {{ai.cases?.length??0}} 条；准备样本不增加模型运行次数。</p></template>
<div v-if="selected" class="detail"><h3>研究输入与证据</h3><button @click="selected=undefined">关闭详情</button><p>规则 {{selected.rule_version}} · 截止 <time :title="'UTC原值：'+utc(selected.as_of)">{{time(selected.as_of)}}</time></p><div v-for="(v,k) in selected.report"><h4>{{reportNames[String(k)]||k}}</h4><pre>{{v===null?'未知':typeof v==='string'?v:JSON.stringify(v,null,2)}}</pre></div><h4>可复算输入快照</h4><pre>{{JSON.stringify(selected.inputs,null,2)}}</pre></div>
</section></template>
<style scoped>.workbench{padding:20px;min-width:0;margin-bottom:20px}.tabs,.filters{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0}article{padding:14px 0;border-bottom:1px solid #25364a}p{line-height:1.65;overflow-wrap:anywhere}select,input{max-width:100%;min-width:0}select{width:min(100%,420px)}label{display:flex;align-items:center;gap:6px}input[type=number]{width:70px}pre{max-height:360px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;background:#0c1526;padding:12px}.detail{border-top:1px solid #547a98}</style>
